CREATE TABLE tbl(a,b PRIMARY KEY) WITHOUT ROWID; INSERT INTO tbl VALUES(100,100),(300,200); CREATE TABLE rlog(idx,old_a,old_b,db_sum_a,db_sum_b,new_a,new_b); CREATE TRIGGER delete_before_row BEFORE DELETE ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),0,0); END; CREATE TRIGGER delete_after_row AFTER DELETE ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),0,0); END;